      validatePath1(fromPath, CONSTS_JDOCS.API.CONTENT, tokenList, PathAccessType.OBJECT);

      JsonNode fromNode = traverse(((JDocument)fromDoc).rootNode, tokenList, false);
      if (fromNode == null) {
